/*!50001 VIEW `vw_desperdicio` AS select `registros_merenda`.`id_registro` AS `id_registro`,`registros_merenda`.`id_escola` AS `id_escola`,`registros_merenda`.`data` AS `data`,`registros_merenda`.`turno` AS `turno`,`registros_merenda`.`refeicoes_preparadas` AS `refeicoes_preparadas`,`registros_merenda`.`refeicoes_servidas` AS `refeicoes_servidas`,`registros_merenda`.`sobras` AS `sobras`,case when `registros_merenda`.`refeicoes_preparadas` > 0 then round(`registros_merenda`.`sobras` / `registros_merenda`.`refeicoes_preparadas` * 100,2) else 0 end AS `percentual_desperdicio` from `registros_merenda` */;
